"""Hash shipping assets, without a recursive self hash or transient intermediates."""
import json,hashlib,sys,struct
from pathlib import Path
out=Path(sys.argv[1]);p=out/'manifest.json';m=json.loads(p.read_text());names=['index.html','pilot.css','pilot.js','contact.json','contact-frontage.png.glb','contact-frontage.optimized.glb','contact-frontage.mobile.glb','lightmap.hdr','lightmap.ktx2','contact-frontage.collision.glb','triggers.json','transcoders/basis_transcoder.js','transcoders/basis_transcoder.wasm','transcoders/LICENSE-three','transparent-graffiti.glb','graffiti/contact-us.png','graffiti/coming-soon.png'];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();m['files']=[{'file':name,'bytes':(out/name).stat().st_size,'sha256':sha(out/name)}for name in names];raw=(out/'contact-frontage.png.glb').read_bytes();length=struct.unpack_from('<I',raw,12)[0];g=json.loads(raw[20:20+length]);m['counts'].update(pbrTextureImages=len(g['images']),uniqueMaterials=len(g['materials']),externalLightmapImages=1,standaloneGraffitiHeadings=2);m['sourceBakedDerivative']={'file':'contact-frontage-baked.blend','bytes':(out/'contact-frontage-baked.blend').stat().st_size,'sha256':sha(out/'contact-frontage-baked.blend')};m['validation']={'uv':'uv-roundtrip-verification.json','rgbm':'rgbm-verification.json','sourceAccounting':'validation/runtime-validation.json','correction':'Texture grain and standalone graffiti alpha; source PBR/geometry/old UVs preserved','sampling':'Linear-HDR mip chain, lossless RGBM numeric alpha, trilinear/anisotropic filtering and MSAA','fullWorldAndNightFidelity':'M2/M3 and physical-device profiling remain separate'};p.write_text(json.dumps(m,indent=2)+'\n');print('MANIFEST_FINALIZED',len(names))
